  try {
    thumbnail = BitmapUtils.rotateImage(thumbnail, path);
  } catch (NullPointerException e) {
    // Handle the null pointer exception, e.g. logging or returning a default value
    e.printStackTrace();
    return null;
  }
  addBitmapToCache(imageKey, thumbnail);
  return thumbnail;
}
